import React, { useState } from 'react';
import api from '../services/api';

const BuscarMotorista = () => {
    const [placa, setPlaca] = useState('');
    const [motorista, setMotorista] = useState(null);
    const [erro, setErro] = useState('');

    const buscarMotorista = () => {
        api.get(`/buscar/${placa}`)
            .then(response => {
                setMotorista(response.data);
                setErro('');
            })
            .catch(() => {
                setMotorista(null);
                setErro('Motorista não encontrado.');
            });
    };

    return (
        <div>
            <h2>Buscar Motorista</h2>
            <input
                type="text"
                placeholder="Digite a placa"
                value={placa}
                onChange={(e) => setPlaca(e.target.value)}
            />
            <button onClick={buscarMotorista}>Buscar</button>

            {motorista && (
                <div>
                    <h3>{motorista.nome}</h3>
                    <p>Placa: {motorista.placa}</p>
                    <p>Modelo: {motorista.modelo} ({motorista.ano})</p>
                    <p>Função: {motorista.funcao}</p>
                </div>
            )}

            {erro && <p>{erro}</p>}
        </div>
    );
};

export default BuscarMotorista;
